```python
class Stream(Protocol):
    def read(self) -> bytes: ...

class FileStream:
    def read(self) -> bytes:
        return self._raw_bytes()

class CompressedStream:
    def __init__(self, wrapped: Stream):
        self._wrapped = wrapped

    def read(self) -> bytes:
        return decompress(self._wrapped.read())

class EncryptedStream:
    def __init__(self, wrapped: Stream):
        self._wrapped = wrapped

    def read(self) -> bytes:
        return decrypt(self._wrapped.read())

stream = EncryptedStream(CompressedStream(FileStream("data.bin")))
```

`stream.read()` decrypts, then decompresses, then reads the raw file — three responsibilities, zero new subclasses, and any layer can be added, removed, or reordered independently.
